-- Recipe: outstanding (#2943) - supply as an attestation counts it: total supply, less frozen
-- balances, less what addresses labelled `treasury` hold (minted but not issued). The
-- treasury addresses are yours to supply: `nuthatch labels import` a set labelling them.
-- `at_time` or `at_block` gives supply and freezes at a report date; the label set is the one
-- imported now, so import the treasury addresses as they were then. Query it:
-- SELECT * FROM fiat_token_v2_2_outstanding
CREATE VIEW fiat_token_v2_2_outstanding AS
SELECT s.total_supply, z.frozen, t.treasury, s.total_supply - z.frozen - t.treasury AS outstanding FROM (SELECT COALESCE(SUM(CASE WHEN lower("from") = '0x0000000000000000000000000000000000000000' THEN CASE WHEN TRY_CAST("value" AS DECIMAL(38,0)) IS NOT NULL THEN CAST("value" AS HUGEINT) END ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN lower("to") = '0x0000000000000000000000000000000000000000' THEN CASE WHEN TRY_CAST("value" AS DECIMAL(38,0)) IS NOT NULL THEN CAST("value" AS HUGEINT) END ELSE 0 END), 0) AS total_supply FROM "fiat_token_v2_2__transfer") s CROSS JOIN (SELECT COALESCE(SUM(balance), 0) AS frozen FROM (SELECT f.account, COALESCE(b.balance, 0) AS balance, f.block_number AS frozen_at FROM (SELECT account, kind, block_number, ROW_NUMBER() OVER (PARTITION BY account ORDER BY block_number DESC, log_index DESC) AS rn FROM (SELECT lower(_account) AS account, 'blacklisted' AS kind, block_number, log_index FROM "fiat_token_v2_2__blacklisted" UNION ALL SELECT lower(_account) AS account, 'unblacklisted' AS kind, block_number, log_index FROM "fiat_token_v2_2__un_blacklisted")) f LEFT JOIN (SELECT addr, SUM(d) AS balance FROM (SELECT lower("to") AS addr, CASE WHEN TRY_CAST("value" AS DECIMAL(38,0)) IS NOT NULL THEN CAST("value" AS HUGEINT) END AS d FROM "fiat_token_v2_2__transfer" UNION ALL SELECT lower("from") AS addr, -CASE WHEN TRY_CAST("value" AS DECIMAL(38,0)) IS NOT NULL THEN CAST("value" AS HUGEINT) END AS d FROM "fiat_token_v2_2__transfer") GROUP BY addr) b ON b.addr = f.account WHERE f.rn = 1 AND f.kind = 'blacklisted')) z CROSS JOIN (SELECT COALESCE(SUM(b.balance), 0) AS treasury FROM (SELECT addr, SUM(d) AS balance FROM (SELECT lower("to") AS addr, CASE WHEN TRY_CAST("value" AS DECIMAL(38,0)) IS NOT NULL THEN CAST("value" AS HUGEINT) END AS d FROM "fiat_token_v2_2__transfer" UNION ALL SELECT lower("from") AS addr, -CASE WHEN TRY_CAST("value" AS DECIMAL(38,0)) IS NOT NULL THEN CAST("value" AS HUGEINT) END AS d FROM "fiat_token_v2_2__transfer") GROUP BY addr) b WHERE b.addr IN (SELECT lower(address) FROM labels WHERE label = 'treasury') AND b.addr NOT IN (SELECT account FROM (SELECT f.account, COALESCE(b.balance, 0) AS balance, f.block_number AS frozen_at FROM (SELECT account, kind, block_number, ROW_NUMBER() OVER (PARTITION BY account ORDER BY block_number DESC, log_index DESC) AS rn FROM (SELECT lower(_account) AS account, 'blacklisted' AS kind, block_number, log_index FROM "fiat_token_v2_2__blacklisted" UNION ALL SELECT lower(_account) AS account, 'unblacklisted' AS kind, block_number, log_index FROM "fiat_token_v2_2__un_blacklisted")) f LEFT JOIN (SELECT addr, SUM(d) AS balance FROM (SELECT lower("to") AS addr, CASE WHEN TRY_CAST("value" AS DECIMAL(38,0)) IS NOT NULL THEN CAST("value" AS HUGEINT) END AS d FROM "fiat_token_v2_2__transfer" UNION ALL SELECT lower("from") AS addr, -CASE WHEN TRY_CAST("value" AS DECIMAL(38,0)) IS NOT NULL THEN CAST("value" AS HUGEINT) END AS d FROM "fiat_token_v2_2__transfer") GROUP BY addr) b ON b.addr = f.account WHERE f.rn = 1 AND f.kind = 'blacklisted'))) t;
